    // The menu bars' icons (NHE-MOD-UI/Menuicons). Each file is an orange
    // shape with a white one on top, which reads as an orange outline round a
    // white fill. Here: the outline alone (the orange shape minus the white,
    // even-odd) in currentColor, and the white fill (.nhe-icon-fill). Inactive:
    // a white outline; active / open (features/bars/bars.css): the outline
    // orange and the white fill shown, exactly as supplied.
    var duo = function (viewBox, edge, fill) {
        return '<svg viewBox="' + viewBox + '" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">' +
            '<path class="nhe-icon-edge" d="' + edge + ' ' + fill + '" fill="currentColor" fill-rule="evenodd"/>' +
            '<path class="nhe-icon-fill" d="' + fill + '" fill="#fff"/></svg>'
    }
